  for (int idx = tid; idx < KTILE * COUT; idx += THREADS) {
    const int co = idx >> 5;
    const int k = idx & 31;
    smem.stage.sW[co][k] = (k < CIN * K * K)
                    ? w[co * (CIN * K * K) + k]
                    : __float2bfloat16(0.0f);
  }
  // Stage the raw input tile (3x3 halo included) into shared memory with
  // coalesced global loads: consecutive threads read consecutive columns
  // of x, replacing the previous scattered im2col global reads.
  for (int idx = tid; idx < CIN * TILE_IH * TILE_IW; idx += THREADS) {
    const int iw = idx % TILE_IW;
    const int r = (idx / TILE_IW) % TILE_IH;
    const int ci = idx / (TILE_IW * TILE_IH);
    const int ih = oh0 + r;
    const int jw = ow0 + iw;
    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (ih < H && jw < W) {
      v = x[((long long)(n * CIN + ci) * H + ih) * W + jw];
    }
    smem.stage.sX[ci][r][iw] = v;
  }
  __syncthreads();
