  // (shared-memory reads only), zero-padding k >= 27.
  for (int idx = tid; idx < TILE_M * KTILE; idx += THREADS) {
    const int m = idx >> 5;
    const int k = idx & 31;
    __nv_bfloat16 v = __float2bfloat16(0.0f);
    if (k < CIN * K * K) {
      const int ci = k / 9;
      const int r = k - ci * 9;
      const int kh = r / 3;
      const int kw = r - kh * 3;
      v = smem.stage.sX[ci][(m >> 4) + kh][(m & 15) + kw];
    }
    smem.stage.sA[m][k] = v;
  }
  __syncthreads();
  wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc[2][2];
#pragma unroll
  for (int i = 0; i < 2; ++i) {
#pragma unroll
    for (int j = 0; j < 2; ++j) {
      wmma::fill_fragment(acc[i][j], 0.0f);
    }
  }
  // 8 warps x 32 pixels = TILE_M = 256; each warp covers two stacked
  // 16-pixel fragments and all 32 output channels (two 16-wide N-fragments).
  const int m0 = warp * 32;
#pragma unroll
  for (int ki = 0; ki < 2; ++ki) {
    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> a[2];
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::col_major> b[2];
