    wmma::load_matrix_sync(a[1], &smem.stage.sA[m0 + 16][ki * 16], KTILE);
    wmma::load_matrix_sync(b[0], &smem.stage.sW[0][ki * 16], KTILE);
    wmma::load_matrix_sync(b[1], &smem.stage.sW[16][ki * 16], KTILE);
