    wmma::mma_sync(acc[0][1], a[0], b[1], acc[0][1]);
    wmma::mma_sync(acc[1][0], a[1], b[0], acc[1][0]);
    wmma::mma_sync(acc[1][1], a[1], b[1], acc[1][1]);
  }
  // All reads of the staging region must finish before the bf16 epilogue
  // buffer overwrites it (sOut16 aliases the staging shared memory).
  __syncthreads();
  // Convert the float accumulator fragments to bf16 in registers and stage
  // them in shared memory (16x16 accumulator layout: lane/4 = row group,
  // (lane%4)*2 = column pair, upper/lower 8-row and 8-column halves).
  const int lane = tid & 31;
  const int frow = lane >> 2;
  const int fcol = (lane & 3) * 2;
#pragma unroll
  for (int i = 0; i < 2; ++i) {
#pragma unroll
    for (int j = 0; j < 2; ++j) {
      const int rb = warp * 32 + i * 16 + frow;
      const int cb = j * 16 + fcol;
#pragma unroll
      for (int e = 0; e < 8; ++e) {
        smem.sOut16[rb + ((e & 2) ? 8 : 0)][cb + (e & 1) + ((e & 4) ? 8 : 0)] =
            __float2bfloat16_rn(acc[i][j].x[e]);
      }
    }
  }
  __syncthreads();
  // Write results back; consecutive threads cover consecutive pixel pairs
  // for coalesced stores (vectorized 4B stores when Wo is even).
  for (int idx = tid; idx < (TILE_M / 2) * COUT; idx += THREADS) {
    const int co = idx >> 7;
    const int pix = (idx & 127) << 1;
    const int oh = oh0 + (pix >> 4);
    const int ow = ow0 + (pix & 15);
    if (oh < Ho && (pix & 15) < 15 && ow + 1 < Wo && ((Wo & 1) == 0)) {
      __nv_bfloat162 v;
      v.x = smem.sOut16[pix][co];
      v.y = smem.sOut16[pix + 1][co];
      *reinterpret_cast<__nv_bfloat162*>(
          &y[((long long)(n * COUT + co) * Ho + oh) * Wo + ow]) = v;
    } else {
      if (oh < Ho && ow < Wo) {
        y[((long long)(n * COUT + co) * Ho + oh) * Wo + ow] = smem.sOut16[pix][co];
      }
      const int oh1 = oh0 + ((pix + 1) >> 4);
      const int ow1 = ow0 + ((pix + 1) & 15);
      if (oh1 < Ho && ow1 < Wo) {
        y[((long long)(n * COUT + co) * Ho + oh1) * Wo + ow1] =
            smem.sOut16[pix + 1][co];
      }
    }
  }
}
